export default JSON.parse(
  "{\n  \"workId\": \"han-fei-zi\",\n  \"chapter\": {\n    \"id\": \"han-fei-zi_ch-40\",\n    \"workId\": \"han-fei-zi\",\n    \"order\": 40,\n    \"title\": \"顯學\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 10,\n    \"passageIds\": [\n      \"han-fei-zi_ch-40_p-1\",\n      \"han-fei-zi_ch-40_p-2\",\n      \"han-fei-zi_ch-40_p-3\",\n      \"han-fei-zi_ch-40_p-4\",\n      \"han-fei-zi_ch-40_p-5\",\n      \"han-fei-zi_ch-40_p-6\",\n      \"han-fei-zi_ch-40_p-7\",\n      \"han-fei-zi_ch-40_p-8\",\n      \"han-fei-zi_ch-40_p-9\",\n      \"han-fei-zi_ch-40_p-10\",\n      \"han-fei-zi_ch-40_p-11\"\n    ],\n    \"tags\": [\n      \"法家\",\n      \"帝王術\",\n      \"法術勢\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"han-fei-zi_ch-40_p-1\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"order\": 1,\n      \"canonicalText\": \"世之顯學，儒、墨也。儒之所至，孔丘也。墨之所至，墨翟也。自孔子之死也，有子張之儒，有子思之儒，有顏氏之儒，有孟氏之儒，有漆雕氏之儒，有仲良氏之儒，有孫氏之儒，有樂正氏之儒。自墨子之死也，有相里氏之墨，有相夫氏之墨，有鄧陵氏之墨。故孔、墨之後，儒分為八，墨離為三，取捨相反、不同，而皆自謂真孔、墨，孔、墨不可復生，將誰使定世之學乎？孔子、墨子俱道堯、舜，而取捨不同，皆自謂真堯、舜，堯、舜不復生，將誰使定儒、墨之誠乎？殷、周七百餘歲，虞、夏二千餘歲，而不能定儒、墨之真，今乃欲審堯、舜之道於三千歲之前，意者其不可必乎！無參驗而必之者、愚也，弗能必而據之者、誣也。故明據先王，必定堯、舜者，非愚則誣也。愚誣之學，雜反之行，明主弗受也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-40_p-1_s-1\",\n        \"han-fei-zi_ch-40_p-1_s-2\",\n        \"han-fei-zi_ch-40_p-1_s-3\",\n        \"han-fei-zi_ch-40_p-1_s-4\",\n        \"han-fei-zi_ch-40_p-1_s-5\",\n        \"han-fei-zi_ch-40_p-1_s-6\",\n        \"han-fei-zi_ch-40_p-1_s-7\",\n        \"han-fei-zi_ch-40_p-1_s-8\",\n        \"han-fei-zi_ch-40_p-1_s-9\",\n        \"han-fei-zi_ch-40_p-1_s-10\",\n        \"han-fei-zi_ch-40_p-1_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"世的顯學，儒、墨啊。儒的所至，孔丘啊。墨的所至，墨翟啊。自孔子的死啊，有子張的儒，有子思的儒，有顏氏的儒，有孟氏的儒，有漆雕氏的儒，有仲良氏的儒，有孫氏的儒，有樂正氏的儒。自墨子的死啊，有相里氏的墨，有相夫氏的墨，有鄧陵氏的墨。所以孔、墨的後，儒分為八，墨離為三，取捨相反、不同，而且皆自謂真孔、墨，孔、墨不可復生，將誰使定世的學乎？孔子、墨子俱道堯、舜，而且取捨不同，皆自謂真堯、舜，堯、舜不復生，將誰使定儒、墨的誠乎？殷、周七百餘歲，虞、夏二千餘歲，而且不能定儒、墨的真，今乃欲審堯、舜的道於三千歲的前，意的人或事他的不可必乎！無參驗而且必的的人或事、愚啊，弗能必而且據的的人或事、誣啊。所以明據先王，必定堯、舜的人或事，絕不是愚則誣啊。愚誣的學，雜反的行，明主弗受啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈顯學〉。韓非深刻融合法、術、勢三大治國精要，此處「世之顯學，儒、墨也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「世」、「顯」、「學」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「世之顯學儒墨也儒之所至孔丘也墨之所至墨翟也自孔子」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「儒之所至，孔丘也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-2\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"order\": 2,\n      \"canonicalText\": \"墨者之葬也，冬日冬服，夏日夏服，桐棺三寸，服喪三月，世主以為儉而禮之。儒者破家而葬，服喪三年，大毀扶杖，世主以為孝而禮之。夫是墨子之儉，將非孔子之侈也；是孔子之孝，將非墨子之戾也。今孝戾、侈儉俱在儒、墨，而上兼禮之。漆雕之議，不色撓，不目逃，行曲則違於臧獲，行直則怒於諸侯，世主以為廉而禮之。宋榮子之議，設不鬥爭，取不隨仇，不羞囹圄，見侮不辱，世主以為寬而禮之。夫是漆雕之廉，將非宋榮之恕也；是宋榮之寬，將非漆雕之暴也。今寬廉、恕暴俱在二子，人主兼而禮之。自愚誣之學、雜反之辭爭，而人主俱聽之，故海內之士，言無定術，行無常議。夫冰炭不同器而久，寒暑不兼時而至，雜反之學不兩立而治，今兼聽雜學繆行同異之辭，安得無亂乎？聽行如此，其於治人又必然矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-40_p-2_s-1\",\n        \"han-fei-zi_ch-40_p-2_s-2\",\n        \"han-fei-zi_ch-40_p-2_s-3\",\n        \"han-fei-zi_ch-40_p-2_s-4\",\n        \"han-fei-zi_ch-40_p-2_s-5\",\n        \"han-fei-zi_ch-40_p-2_s-6\",\n        \"han-fei-zi_ch-40_p-2_s-7\",\n        \"han-fei-zi_ch-40_p-2_s-8\",\n        \"han-fei-zi_ch-40_p-2_s-9\",\n        \"han-fei-zi_ch-40_p-2_s-10\",\n        \"han-fei-zi_ch-40_p-2_s-11\",\n        \"han-fei-zi_ch-40_p-2_s-12\",\n        \"han-fei-zi_ch-40_p-2_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"墨的人或事的葬啊，冬日冬服，夏日夏服，桐棺三寸，服喪三月，世主以為儉而且禮的。儒的人或事破家而且葬，服喪三年，大毀扶杖，世主以為孝而且禮的。夫是墨子的儉，將絕不是孔子的侈啊；是孔子的孝，將絕不是墨子的戾啊。今孝戾、侈儉俱在儒、墨，而且上兼禮的。漆雕的議，不色撓，不目逃，行曲則違於臧獲，行直則怒於諸侯，世主以為廉而且禮的。宋榮子的議，設不鬥爭，取不隨仇，不羞囹圄，見侮不辱，世主以為寬而且禮的。夫是漆雕的廉，將絕不是宋榮的恕啊；是宋榮的寬，將絕不是漆雕的暴啊。今寬廉、恕暴俱在二子，人主兼而且禮的。自愚誣的學、雜反的辭爭，而且人主俱聽的，所以海內的士，言無定督察權術，行無常議。夫冰炭不同器而且久，寒暑不兼時而且至，雜反的學不兩立而且治，今兼聽雜學繆行同異的辭，安得無亂乎？聽行如此，他的於治人又必然矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈顯學〉。韓非深刻融合法、術、勢三大治國精要，此處「墨者之葬也，冬日冬服，夏日夏服，桐棺三寸，服喪三月，世主以為儉而禮之」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「墨」、「葬」、「冬」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「墨者之葬也冬日冬服夏日夏服桐棺三寸服喪三月世主以」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「儒者破家而葬，服喪三年，大毀扶杖，世主以為孝而禮之」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-3\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"order\": 3,\n      \"canonicalText\": \"今世之學士語治者多曰：「與貧窮地以實無資。」今夫與人相若也，無豐年旁入之利而獨以完給者，非力則儉也。與人相若也，無饑饉疾疚禍罪之殃獨以貧窮者，非侈則墯也。侈而墯者貧，而力而儉者富。今上徵斂於富人以佈施於貧家，是奪力儉而與侈墯也。而欲索民之疾作而節用，不可得也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-40_p-3_s-1\",\n        \"han-fei-zi_ch-40_p-3_s-2\",\n        \"han-fei-zi_ch-40_p-3_s-3\",\n        \"han-fei-zi_ch-40_p-3_s-4\",\n        \"han-fei-zi_ch-40_p-3_s-5\",\n        \"han-fei-zi_ch-40_p-3_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今世的學士語治的人或事多說道：與貧窮地以實無資。如今社會上的與人相若啊，無豐年旁入的利而且獨以完給的人或事，絕不是力則儉啊。與人相若啊，無饑饉疾疚禍罪的殃獨以貧窮的人或事，絕不是侈則墯啊。侈而且墯的人或事貧，而且力而且儉的人或事富。今上徵斂於富人以佈施於貧家，是奪力儉而且與侈墯啊。而且欲索民的疾作而且節用，不可得啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈顯學〉。韓非深刻融合法、術、勢三大治國精要，此處「今世之學士語治者多曰：「與貧窮地以實無資」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「今」、「世」、「學」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「今世之學士語治者多曰與貧窮地以實無資今夫與人相若」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」今夫與人相若也，無豐年旁入之利而獨以完給者，非力則儉也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-4\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"order\": 4,\n      \"canonicalText\": \"今有人於此，義不入危城，不處軍旅，不以天下大利易其脛一毛，世主必從而禮之，貴其智而高其行，以為輕物重生之士也。夫上所以陳良田大宅、設爵祿，所以易民死命也，今上尊貴輕物重生之士、而索民之出死而重殉上事，不可得也。藏書策、習談論、聚徒役、服文學而議說，世主必從而禮之，曰：「敬賢士，先王之道也。」夫吏之所稅，耕者也；而上之所養，學士也。耕者則重稅，學士則多賞，而索民之疾作而少言談，不可得也。立節參民，執操不侵，怨言過於耳必隨之以劍，世主必從而禮之，以為自好之士。夫斬首之勞不賞，而家鬥之勇尊顯，而索民之疾戰距敵而無私鬥，不可得也。國平則養儒俠，難至則用介士，所養者非所用，所用者非所養，此所以亂也。且夫人主於聽學也，若是其言、宜布之官而用其身，若非其言、宜去其身而息其端。今以為是也而弗布於官，以為非也而不息其端，是而不用，非而不息，亂亡之道也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-40_p-4_s-1\",\n        \"han-fei-zi_ch-40_p-4_s-2\",\n        \"han-fei-zi_ch-40_p-4_s-3\",\n        \"han-fei-zi_ch-40_p-4_s-4\",\n        \"han-fei-zi_ch-40_p-4_s-5\",\n        \"han-fei-zi_ch-40_p-4_s-6\",\n        \"han-fei-zi_ch-40_p-4_s-7\",\n        \"han-fei-zi_ch-40_p-4_s-8\",\n        \"han-fei-zi_ch-40_p-4_s-9\",\n        \"han-fei-zi_ch-40_p-4_s-10\",\n        \"han-fei-zi_ch-40_p-4_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今有人於此，義不入危城，不處軍旅，不以天下大利易他的脛一毛，世主必從而且禮的，貴他的智而且高他的行，以為輕物重生的士啊。夫上所以陳良田大宅、設爵祿，所以易民死命啊，今上尊貴輕物重生的士、而且索民的出死而且重殉上事，不可得啊。藏書策、習談論、聚徒役、服文學而且議說，世主必從而且禮的，說道：敬賢士，先王的道啊。夫吏的所稅，耕的人或事啊；而且上的所養，學士啊。耕的人或事則重稅，學士則多賞賜，而且索民的疾作而且少言談，不可得啊。立節參民，執操不侵，怨言過於耳必隨的以劍，世主必從而且禮的，以為自好的士。夫斬首的勞不賞賜，而且家鬥的勇尊顯，而且索民的疾戰距敵而且無私鬥，不可得啊。國平則養儒俠，難至則用介士，所養的人或事絕不是所用，所用的人或事絕不是所養，此所以亂啊。再的人或事況且人主於聽學啊，若是他的言、宜布的官而且用他的身，若絕不是他的言、宜去他的身而且息他的端。今以為是啊而且弗布於官，以為絕不是啊而且不息他的端，是而且不用，絕不是而且不息，亂亡的道啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈顯學〉。韓非深刻融合法、術、勢三大治國精要，此處「今有人於此，義不入危城，不處軍旅，不以天下大利易其脛一毛，世主必從而禮之，貴其智而高其行，以為輕物重生之士也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「今」、「有」、「人」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「今有人於此義不入危城不處軍旅不以天下大利易其脛一」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「夫上所以陳良田大宅、設爵祿，所以易民死命也，今上尊貴輕物重生之士、而索民之出死而重殉上事，不可得也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"order\": 5,\n      \"canonicalText\": \"澹臺子羽，君子之容也，仲尼幾而取之，與處久而行不稱其貌。宰予之辭，雅而文也，仲尼幾而取之，與處而智不充其辯。故孔子曰：「以容取人乎，失之子羽；以言取人乎，失之宰予。」故以仲尼之智而有失實之聲。今之新辯濫乎宰予，而世主之聽眩乎仲尼，為悅其言，因任其身，則焉得無失乎？是以魏任孟卯之辯而有華下之患，趙任馬服之辯而有長平之禍；此二者，任辯之失也。夫視鍛錫而察青黃，區冶不能以必劍；水擊鵠雁，陸斷駒馬，則臧獲不疑鈍利。發齒吻形容，伯樂不能以必馬；授車就駕而觀其末塗，則臧獲不疑駑良。觀容服，聽辭言，仲尼不能以必士；試之官職，課其功伐，則庸人不疑於愚智。故明主之吏，宰相必起於州部，猛將必發於卒伍。夫有功者必賞，則爵祿厚而愈勸；遷官襲級，則官職大而愈治。夫爵祿大而官職治，王之道也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-40_p-5_s-1\",\n        \"han-fei-zi_ch-40_p-5_s-2\",\n        \"han-fei-zi_ch-40_p-5_s-3\",\n        \"han-fei-zi_ch-40_p-5_s-4\",\n        \"han-fei-zi_ch-40_p-5_s-5\",\n        \"han-fei-zi_ch-40_p-5_s-6\",\n        \"han-fei-zi_ch-40_p-5_s-7\",\n        \"han-fei-zi_ch-40_p-5_s-8\",\n        \"han-fei-zi_ch-40_p-5_s-9\",\n        \"han-fei-zi_ch-40_p-5_s-10\",\n        \"han-fei-zi_ch-40_p-5_s-11\",\n        \"han-fei-zi_ch-40_p-5_s-12\",\n        \"han-fei-zi_ch-40_p-5_s-13\",\n        \"han-fei-zi_ch-40_p-5_s-14\",\n        \"han-fei-zi_ch-40_p-5_s-15\",\n        \"han-fei-zi_ch-40_p-5_s-16\",\n        \"han-fei-zi_ch-40_p-5_s-17\",\n        \"han-fei-zi_ch-40_p-5_s-18\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"澹臺子羽，國君子的容啊，仲尼幾而且取的，與處久而且行不稱他的貌。宰予的辭，雅而且文啊，仲尼幾而且取的，與處而且智不充他的辯。所以孔子說道：以容取人乎，失的子羽；以言取人乎，失的宰予。所以以仲尼的智而且有失實的聲。今的新辯濫乎宰予，而且世主的聽眩乎仲尼，為悅他的言，因任他的身，則焉得無失乎？是以魏任孟卯的辯而且有華下的患，趙任馬服的辯而且有長平的禍；此二的人或事，任辯的失啊。夫視鍛錫而且察青黃，區冶不能以必劍；水擊鵠雁，陸斷駒馬，則臧獲不疑鈍利。發齒吻形容，伯樂不能以必馬；授車就駕而且觀他的末塗，則臧獲不疑駑良。觀容服，聽辭言，仲尼不能以必士；試的官職，課他的功伐，則庸人不疑於愚智。所以明主的吏，宰相必起於州部，猛將必發於卒伍。夫有功的人或事必賞賜，則爵祿厚而且愈勸；遷官襲級，則官職大而且愈治。夫爵祿大而且官職治，王的道啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈顯學〉。韓非深刻融合法、術、勢三大治國精要，此處「澹臺子羽，君子之容也，仲尼幾而取之，與處久而行不稱其貌」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「澹」、「臺」、「子」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「澹臺子羽君子之容也仲尼幾而取之與處久而行不稱其貌」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「宰予之辭，雅而文也，仲尼幾而取之，與處而智不充其辯」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-6\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"order\": 6,\n      \"canonicalText\": \"磐石千里，不可謂富；象人百萬，不可謂強。石非不大，數非不眾也，而不可謂富強者，磐不生粟，象人不可使距敵也。今商官技藝之士亦不墾而食，是地不墾與磐石一貫也。儒俠毋軍勞、顯而榮者則民不使，與象人同事也。夫禍知磐石象人，而不知禍商官儒俠為不墾之地、不使之民，不知事類者也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-40_p-6_s-1\",\n        \"han-fei-zi_ch-40_p-6_s-2\",\n        \"han-fei-zi_ch-40_p-6_s-3\",\n        \"han-fei-zi_ch-40_p-6_s-4\",\n        \"han-fei-zi_ch-40_p-6_s-5\",\n        \"han-fei-zi_ch-40_p-6_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"磐石千里，不可謂富；象人百萬，不可謂強。石絕不是不大，數絕不是不眾啊，而且不可謂富強的人或事，磐不生粟，象人不可使距敵啊。今商官技藝的士亦不墾而且食，是地不墾與磐石一貫啊。儒俠毋軍勞、顯而且榮的人或事則民不使，與象人同事啊。夫禍知磐石象人，而且不知禍商官儒俠為不墾的地、不使的民，不知事類的人或事啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈顯學〉。韓非深刻融合法、術、勢三大治國精要，此處「磐石千里，不可謂富」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「磐」、「石」、「千」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「磐石千里不可謂富象人百萬不可謂強石非不大數非不眾」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「象人百萬，不可謂強」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-7\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"order\": 7,\n      \"canonicalText\": \"故敵國之君王雖說吾義，吾弗入貢而臣；關內之侯雖非吾行，吾必使執禽而朝。是故力多則人朝，力寡則朝於人，故明君務力。夫嚴家無悍虜，而慈母有敗子，吾以此知威勢之可以禁暴，而德厚之不足以止亂也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-40_p-7_s-1\",\n        \"han-fei-zi_ch-40_p-7_s-2\",\n        \"han-fei-zi_ch-40_p-7_s-3\",\n        \"han-fei-zi_ch-40_p-7_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以敵國的國君王雖說吾義，吾弗入貢而且臣屬；關內的侯雖絕不是吾行，吾必使執禽而且朝。正因為如此力多則人朝，力寡則朝於人，所以明國君務力。夫嚴家無悍虜，而且慈母有敗子，吾以此知威權位威勢的可以禁暴，而且德厚的不足以止亂啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈顯學〉。韓非深刻融合法、術、勢三大治國精要，此處「故敵國之君王雖說吾義，吾弗入貢而臣」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「敵」、「國」、「君」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「故敵國之君王雖說吾義吾弗入貢而臣關內之侯雖非吾行」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「關內之侯雖非吾行，吾必使執禽而朝」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-8\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"order\": 8,\n      \"canonicalText\": \"夫聖人之治國，不恃人之為吾善也，而用其不得為非也。恃人之為吾善也，境內不什數；用人不得為非，一國可使齊。為治者用眾而舍寡，故不務德而務法。夫必恃自直之箭，百世無矢；恃自圜之木，千世無輪矣。自直之箭、自圜之木，百世無有一，然而世皆乘車射禽者何也？隱栝之道用也。雖有不恃隱栝而有自直之箭、自圜之木，良工弗貴也，何則？乘者非一人，射者非一發也。不恃賞罰而恃自善之民，明主弗貴也，何則？國法不可失，而所治非一人也。故有術之君，不隨適然之善，而行必然之道。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-40_p-8_s-1\",\n        \"han-fei-zi_ch-40_p-8_s-2\",\n        \"han-fei-zi_ch-40_p-8_s-3\",\n        \"han-fei-zi_ch-40_p-8_s-4\",\n        \"han-fei-zi_ch-40_p-8_s-5\",\n        \"han-fei-zi_ch-40_p-8_s-6\",\n        \"han-fei-zi_ch-40_p-8_s-7\",\n        \"han-fei-zi_ch-40_p-8_s-8\",\n        \"han-fei-zi_ch-40_p-8_s-9\",\n        \"han-fei-zi_ch-40_p-8_s-10\",\n        \"han-fei-zi_ch-40_p-8_s-11\",\n        \"han-fei-zi_ch-40_p-8_s-12\",\n        \"han-fei-zi_ch-40_p-8_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"夫聖人的治國，不恃人的為吾善啊，而且用他的不得為絕不是啊。恃人的為吾善啊，境內不什數；用人不得為絕不是，一國可使齊。為治的人或事用眾而且舍寡，所以不務德而且務法規法令。夫必恃自直的箭，百世無矢；恃自圜的木，千世無輪矣。自直的箭、自圜的木，百世無有一，然而且世皆乘車射禽的人或事何啊？隱栝的道用啊。雖有不恃隱栝而且有自直的箭、自圜的木，良工弗貴啊，何則？乘的人或事絕不是一人，射的人或事絕不是一發啊。不恃賞賜與刑罰而且恃自善的民，明主弗貴啊，何則？國法規法令不可失，而且所治絕不是一人啊。所以有督察權術的國君，不隨適然的善，而且行必然的道。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈顯學〉。韓非深刻融合法、術、勢三大治國精要，此處「夫聖人之治國，不恃人之為吾善也，而用其不得為非也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「聖」、「人」、「治」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「夫聖人之治國不恃人之為吾善也而用其不得為非也恃人」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「恃人之為吾善也，境內不什數」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-9\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"order\": 9,\n      \"canonicalText\": \"今或謂人曰：「使子必智而壽」，則世必以為狂。夫智、性也，壽、命也，性命者，非所學於人也，而以人之所不能為說人，此世之所以謂之為狂也。謂之不能，然則是諭也。夫諭、性也。以仁義教人，是以智與壽說也，有度之主弗受也。故善毛嗇、西施之美，無益吾面，用脂澤粉黛則倍其初。言先王之仁義，無益於治，明吾法度，必吾賞罰者亦國之脂澤粉黛也。故明主急其助而緩其頌，故不道仁義。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-40_p-9_s-1\",\n        \"han-fei-zi_ch-40_p-9_s-2\",\n        \"han-fei-zi_ch-40_p-9_s-3\",\n        \"han-fei-zi_ch-40_p-9_s-4\",\n        \"han-fei-zi_ch-40_p-9_s-5\",\n        \"han-fei-zi_ch-40_p-9_s-6\",\n        \"han-fei-zi_ch-40_p-9_s-7\",\n        \"han-fei-zi_ch-40_p-9_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今或謂人說道：使子必智而且壽，則世必以為狂。夫智、性啊，壽、命啊，性命的人或事，絕不是所學於人啊，而且以人的所不能為說人，此世的所以謂的為狂啊。謂的不能，然則是諭啊。夫諭、性啊。以仁義教人，是以智與壽說啊，有度的主弗受啊。所以善毛嗇、西施的美，無益吾面，用脂澤粉黛則倍他的初。言先王的仁義，無益於治，明吾法規法令度，必吾賞賜與刑罰的人或事亦國的脂澤粉黛啊。所以明主急他的助而且緩他的頌，所以不道仁義。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈顯學〉。韓非深刻融合法、術、勢三大治國精要，此處「今或謂人曰：「使子必智而壽」，則世必以為狂」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「今」、「或」、「謂」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「今或謂人曰使子必智而壽則世必以為狂夫智性也壽命也」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「夫智、性也，壽、命也，性命者，非所學於人也，而以人之所不能為說人，此世之所以謂之為狂也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-10\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"order\": 10,\n      \"canonicalText\": \"今巫祝之祝人曰：「使若千秋萬歲。」千秋萬歲之聲聒耳，而一日之壽無徵於人，此人所以簡巫祝也。今世儒者之說人主，不善今之所以為治，而語已治之功；不審官法之事，不察姦邪之情，而皆道上古之傳，譽先王之成功。儒者飾辭曰：「聽吾言則可以霸王。」此說者之巫祝，有度之主不受也。故明主舉實事，去無用；不道仁義者故，不聽學者之言。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-40_p-10_s-1\",\n        \"han-fei-zi_ch-40_p-10_s-2\",\n        \"han-fei-zi_ch-40_p-10_s-3\",\n        \"han-fei-zi_ch-40_p-10_s-4\",\n        \"han-fei-zi_ch-40_p-10_s-5\",\n        \"han-fei-zi_ch-40_p-10_s-6\",\n        \"han-fei-zi_ch-40_p-10_s-7\",\n        \"han-fei-zi_ch-40_p-10_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今巫祝的祝人說道：使若千秋萬歲。千秋萬歲的聲聒耳，而且一日的壽無徵於人，此人所以簡巫祝啊。今世儒的人或事的說人主，不善今的所以為治，而且語已治的功；不審官法規法令的事，不察姦邪的情，而且皆道上古的傳，譽先王的成功。儒的人或事飾辭說道：聽吾言則可以霸王。此說的人或事的巫祝，有度的主不受啊。所以明主舉實事，去無用；不道仁義的人或事所以，不聽學的人或事的言。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈顯學〉。韓非深刻融合法、術、勢三大治國精要，此處「今巫祝之祝人曰：「使若千秋萬歲」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「今」、「巫」、「祝」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「今巫祝之祝人曰使若千秋萬歲千秋萬歲之聲聒耳而一日」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」千秋萬歲之聲聒耳，而一日之壽無徵於人，此人所以簡巫祝也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-11\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"order\": 11,\n      \"canonicalText\": \"今不知治者必曰：「得民之心。」欲得民之心而可以為治，則是伊尹、管仲無所用也，將聽民而已矣。民智之不可用，猶嬰兒之心也。夫嬰兒不剔首則腹痛，不揊痤則寖益，剔首、揊痤必一人抱之，慈母治之，然猶啼呼不止，嬰兒子不知犯其所小苦致其所大利也。今上急耕田墾草以厚民產也，而以上為酷；修刑重罰以為禁邪也，而以上為嚴；徵賦錢粟以實倉庫、且以救饑饉備軍旅也，而以上為貪；境內必知介，而無私解，併力疾鬥所以禽虜也，而以上為暴。此四者所以治安也，而民不知悅也。夫求聖通之士者，為民知之不足師用。昔禹決江濬河而民聚瓦石，子產開畝樹桑鄭人謗訾。禹利天下，子產存鄭，皆以受謗，夫民智之不足用亦明矣。故舉士而求賢智，為政而期適民，皆亂之端，未可與為治也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-40_p-11_s-1\",\n        \"han-fei-zi_ch-40_p-11_s-2\",\n        \"han-fei-zi_ch-40_p-11_s-3\",\n        \"han-fei-zi_ch-40_p-11_s-4\",\n        \"han-fei-zi_ch-40_p-11_s-5\",\n        \"han-fei-zi_ch-40_p-11_s-6\",\n        \"han-fei-zi_ch-40_p-11_s-7\",\n        \"han-fei-zi_ch-40_p-11_s-8\",\n        \"han-fei-zi_ch-40_p-11_s-9\",\n        \"han-fei-zi_ch-40_p-11_s-10\",\n        \"han-fei-zi_ch-40_p-11_s-11\",\n        \"han-fei-zi_ch-40_p-11_s-12\",\n        \"han-fei-zi_ch-40_p-11_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今不知治的人或事必說道：得民的心。欲得民的心而且可以為治，則是伊尹、管仲無所用啊，將聽民而且已矣。民智的不可用，猶嬰兒的心啊。夫嬰兒不剔首則腹痛，不揊痤則寖益，剔首、揊痤必一人抱的，慈母治的，然猶啼呼不止，嬰兒子不知犯他的所小苦致他的所大利啊。今上急耕田墾草以厚民產啊，而且以上為酷；修刑重刑罰以為禁邪啊，而且以上為嚴；徵賦錢粟以實倉庫、且以救饑饉備軍旅啊，而且以上為貪；境內必知介，而且無私解，併力疾鬥所以禽虜啊，而且以上為暴。此四的人或事所以治安啊，而且民不知悅啊。夫求聖通的士的人或事，為民知的不足師用。昔禹決江濬河而且民聚瓦石，子產開畝樹桑鄭人謗訾。禹利天下，子產存鄭，皆以受謗，夫民智的不足用亦明矣。所以舉士而且求賢智，為政而且期適民，皆亂的端，未可與為治啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈顯學〉。韓非深刻融合法、術、勢三大治國精要，此處「今不知治者必曰：「得民之心」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「今」、「不」、「知」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「今不知治者必曰得民之心欲得民之心而可以為治則是伊」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」欲得民之心而可以為治，則是伊尹、管仲無所用也，將聽民而已矣」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"han-fei-zi_ch-40_p-1_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"世之顯學，儒、墨也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-1_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"儒之所至，孔丘也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-1_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"墨之所至，墨翟也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-1_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"自孔子之死也，有子張之儒，有子思之儒，有顏氏之儒，有孟氏之儒，有漆雕氏之儒，有仲良氏之儒，有孫氏之儒，有樂正氏之儒。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-1_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"自墨子之死也，有相里氏之墨，有相夫氏之墨，有鄧陵氏之墨。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-1_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"故孔、墨之後，儒分為八，墨離為三，取捨相反、不同，而皆自謂真孔、墨，孔、墨不可復生，將誰使定世之學乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-1_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-1\",\n      \"order\": 7,\n      \"canonicalText\": \"孔子、墨子俱道堯、舜，而取捨不同，皆自謂真堯、舜，堯、舜不復生，將誰使定儒、墨之誠乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-1_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-1\",\n      \"order\": 8,\n      \"canonicalText\": \"殷、周七百餘歲，虞、夏二千餘歲，而不能定儒、墨之真，今乃欲審堯、舜之道於三千歲之前，意者其不可必乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-1_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-1\",\n      \"order\": 9,\n      \"canonicalText\": \"無參驗而必之者、愚也，弗能必而據之者、誣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-1_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-1\",\n      \"order\": 10,\n      \"canonicalText\": \"故明據先王，必定堯、舜者，非愚則誣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-1_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-1\",\n      \"order\": 11,\n      \"canonicalText\": \"愚誣之學，雜反之行，明主弗受也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-2_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"墨者之葬也，冬日冬服，夏日夏服，桐棺三寸，服喪三月，世主以為儉而禮之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-2_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"儒者破家而葬，服喪三年，大毀扶杖，世主以為孝而禮之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-2_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"夫是墨子之儉，將非孔子之侈也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-2_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"是孔子之孝，將非墨子之戾也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-2_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"今孝戾、侈儉俱在儒、墨，而上兼禮之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-2_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-2\",\n      \"order\": 6,\n      \"canonicalText\": \"漆雕之議，不色撓，不目逃，行曲則違於臧獲，行直則怒於諸侯，世主以為廉而禮之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-2_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-2\",\n      \"order\": 7,\n      \"canonicalText\": \"宋榮子之議，設不鬥爭，取不隨仇，不羞囹圄，見侮不辱，世主以為寬而禮之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-2_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-2\",\n      \"order\": 8,\n      \"canonicalText\": \"夫是漆雕之廉，將非宋榮之恕也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-2_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-2\",\n      \"order\": 9,\n      \"canonicalText\": \"是宋榮之寬，將非漆雕之暴也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-2_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-2\",\n      \"order\": 10,\n      \"canonicalText\": \"今寬廉、恕暴俱在二子，人主兼而禮之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-2_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-2\",\n      \"order\": 11,\n      \"canonicalText\": \"自愚誣之學、雜反之辭爭，而人主俱聽之，故海內之士，言無定術，行無常議。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-2_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-2\",\n      \"order\": 12,\n      \"canonicalText\": \"夫冰炭不同器而久，寒暑不兼時而至，雜反之學不兩立而治，今兼聽雜學繆行同異之辭，安得無亂乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-2_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-2\",\n      \"order\": 13,\n      \"canonicalText\": \"聽行如此，其於治人又必然矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-3_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"今世之學士語治者多曰：「與貧窮地以實無資。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-3_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"」今夫與人相若也，無豐年旁入之利而獨以完給者，非力則儉也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-3_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"與人相若也，無饑饉疾疚禍罪之殃獨以貧窮者，非侈則墯也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-3_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"侈而墯者貧，而力而儉者富。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-3_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"今上徵斂於富人以佈施於貧家，是奪力儉而與侈墯也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-3_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"而欲索民之疾作而節用，不可得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-4_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"今有人於此，義不入危城，不處軍旅，不以天下大利易其脛一毛，世主必從而禮之，貴其智而高其行，以為輕物重生之士也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-4_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"夫上所以陳良田大宅、設爵祿，所以易民死命也，今上尊貴輕物重生之士、而索民之出死而重殉上事，不可得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-4_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"藏書策、習談論、聚徒役、服文學而議說，世主必從而禮之，曰：「敬賢士，先王之道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-4_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"」夫吏之所稅，耕者也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-4_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"而上之所養，學士也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-4_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"耕者則重稅，學士則多賞，而索民之疾作而少言談，不可得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-4_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"立節參民，執操不侵，怨言過於耳必隨之以劍，世主必從而禮之，以為自好之士。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-4_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"夫斬首之勞不賞，而家鬥之勇尊顯，而索民之疾戰距敵而無私鬥，不可得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-4_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-4\",\n      \"order\": 9,\n      \"canonicalText\": \"國平則養儒俠，難至則用介士，所養者非所用，所用者非所養，此所以亂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-4_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-4\",\n      \"order\": 10,\n      \"canonicalText\": \"且夫人主於聽學也，若是其言、宜布之官而用其身，若非其言、宜去其身而息其端。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-4_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-4\",\n      \"order\": 11,\n      \"canonicalText\": \"今以為是也而弗布於官，以為非也而不息其端，是而不用，非而不息，亂亡之道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"澹臺子羽，君子之容也，仲尼幾而取之，與處久而行不稱其貌。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"宰予之辭，雅而文也，仲尼幾而取之，與處而智不充其辯。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"故孔子曰：「以容取人乎，失之子羽；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"以言取人乎，失之宰予。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"」故以仲尼之智而有失實之聲。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"今之新辯濫乎宰予，而世主之聽眩乎仲尼，為悅其言，因任其身，則焉得無失乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 7,\n      \"canonicalText\": \"是以魏任孟卯之辯而有華下之患，趙任馬服之辯而有長平之禍；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 8,\n      \"canonicalText\": \"此二者，任辯之失也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 9,\n      \"canonicalText\": \"夫視鍛錫而察青黃，區冶不能以必劍；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 10,\n      \"canonicalText\": \"水擊鵠雁，陸斷駒馬，則臧獲不疑鈍利。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 11,\n      \"canonicalText\": \"發齒吻形容，伯樂不能以必馬；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 12,\n      \"canonicalText\": \"授車就駕而觀其末塗，則臧獲不疑駑良。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 13,\n      \"canonicalText\": \"觀容服，聽辭言，仲尼不能以必士；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 14,\n      \"canonicalText\": \"試之官職，課其功伐，則庸人不疑於愚智。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 15,\n      \"canonicalText\": \"故明主之吏，宰相必起於州部，猛將必發於卒伍。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 16,\n      \"canonicalText\": \"夫有功者必賞，則爵祿厚而愈勸；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 17,\n      \"canonicalText\": \"遷官襲級，則官職大而愈治。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-5_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-5\",\n      \"order\": 18,\n      \"canonicalText\": \"夫爵祿大而官職治，王之道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-6_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"磐石千里，不可謂富；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-6_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"象人百萬，不可謂強。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-6_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"石非不大，數非不眾也，而不可謂富強者，磐不生粟，象人不可使距敵也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-6_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"今商官技藝之士亦不墾而食，是地不墾與磐石一貫也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-6_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"儒俠毋軍勞、顯而榮者則民不使，與象人同事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-6_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"夫禍知磐石象人，而不知禍商官儒俠為不墾之地、不使之民，不知事類者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-7_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"故敵國之君王雖說吾義，吾弗入貢而臣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-7_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"關內之侯雖非吾行，吾必使執禽而朝。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-7_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"是故力多則人朝，力寡則朝於人，故明君務力。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-7_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"夫嚴家無悍虜，而慈母有敗子，吾以此知威勢之可以禁暴，而德厚之不足以止亂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-8_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"夫聖人之治國，不恃人之為吾善也，而用其不得為非也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-8_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"恃人之為吾善也，境內不什數；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-8_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"用人不得為非，一國可使齊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-8_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"為治者用眾而舍寡，故不務德而務法。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-8_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"夫必恃自直之箭，百世無矢；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-8_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"恃自圜之木，千世無輪矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-8_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-8\",\n      \"order\": 7,\n      \"canonicalText\": \"自直之箭、自圜之木，百世無有一，然而世皆乘車射禽者何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-8_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-8\",\n      \"order\": 8,\n      \"canonicalText\": \"隱栝之道用也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-8_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-8\",\n      \"order\": 9,\n      \"canonicalText\": \"雖有不恃隱栝而有自直之箭、自圜之木，良工弗貴也，何則？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-8_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-8\",\n      \"order\": 10,\n      \"canonicalText\": \"乘者非一人，射者非一發也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-8_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-8\",\n      \"order\": 11,\n      \"canonicalText\": \"不恃賞罰而恃自善之民，明主弗貴也，何則？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-8_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-8\",\n      \"order\": 12,\n      \"canonicalText\": \"國法不可失，而所治非一人也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-8_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-8\",\n      \"order\": 13,\n      \"canonicalText\": \"故有術之君，不隨適然之善，而行必然之道。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-9_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"今或謂人曰：「使子必智而壽」，則世必以為狂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-9_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"夫智、性也，壽、命也，性命者，非所學於人也，而以人之所不能為說人，此世之所以謂之為狂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-9_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"謂之不能，然則是諭也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-9_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"夫諭、性也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-9_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-9\",\n      \"order\": 5,\n      \"canonicalText\": \"以仁義教人，是以智與壽說也，有度之主弗受也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-9_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-9\",\n      \"order\": 6,\n      \"canonicalText\": \"故善毛嗇、西施之美，無益吾面，用脂澤粉黛則倍其初。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-9_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-9\",\n      \"order\": 7,\n      \"canonicalText\": \"言先王之仁義，無益於治，明吾法度，必吾賞罰者亦國之脂澤粉黛也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-9_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-9\",\n      \"order\": 8,\n      \"canonicalText\": \"故明主急其助而緩其頌，故不道仁義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-10_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"今巫祝之祝人曰：「使若千秋萬歲。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-10_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"」千秋萬歲之聲聒耳，而一日之壽無徵於人，此人所以簡巫祝也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-10_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"今世儒者之說人主，不善今之所以為治，而語已治之功；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-10_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"不審官法之事，不察姦邪之情，而皆道上古之傳，譽先王之成功。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-10_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-10\",\n      \"order\": 5,\n      \"canonicalText\": \"儒者飾辭曰：「聽吾言則可以霸王。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-10_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-10\",\n      \"order\": 6,\n      \"canonicalText\": \"」此說者之巫祝，有度之主不受也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-10_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-10\",\n      \"order\": 7,\n      \"canonicalText\": \"故明主舉實事，去無用；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-10_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-10\",\n      \"order\": 8,\n      \"canonicalText\": \"不道仁義者故，不聽學者之言。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-11_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"今不知治者必曰：「得民之心。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-11_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"」欲得民之心而可以為治，則是伊尹、管仲無所用也，將聽民而已矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-11_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"民智之不可用，猶嬰兒之心也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-11_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-11\",\n      \"order\": 4,\n      \"canonicalText\": \"夫嬰兒不剔首則腹痛，不揊痤則寖益，剔首、揊痤必一人抱之，慈母治之，然猶啼呼不止，嬰兒子不知犯其所小苦致其所大利也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-11_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-11\",\n      \"order\": 5,\n      \"canonicalText\": \"今上急耕田墾草以厚民產也，而以上為酷；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-11_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-11\",\n      \"order\": 6,\n      \"canonicalText\": \"修刑重罰以為禁邪也，而以上為嚴；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-11_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-11\",\n      \"order\": 7,\n      \"canonicalText\": \"徵賦錢粟以實倉庫、且以救饑饉備軍旅也，而以上為貪；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-11_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-11\",\n      \"order\": 8,\n      \"canonicalText\": \"境內必知介，而無私解，併力疾鬥所以禽虜也，而以上為暴。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-11_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-11\",\n      \"order\": 9,\n      \"canonicalText\": \"此四者所以治安也，而民不知悅也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-11_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-11\",\n      \"order\": 10,\n      \"canonicalText\": \"夫求聖通之士者，為民知之不足師用。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-11_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-11\",\n      \"order\": 11,\n      \"canonicalText\": \"昔禹決江濬河而民聚瓦石，子產開畝樹桑鄭人謗訾。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-11_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-11\",\n      \"order\": 12,\n      \"canonicalText\": \"禹利天下，子產存鄭，皆以受謗，夫民智之不足用亦明矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-40_p-11_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-40\",\n      \"passageId\": \"han-fei-zi_ch-40_p-11\",\n      \"order\": 13,\n      \"canonicalText\": \"故舉士而求賢智，為政而期適民，皆亂之端，未可與為治也。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
